WITH scored AS (SELECT *, LEAD(amount, 2) OVER w_part AS next_amount, DENSE_RANK() OVER w_hist AS amount_dense_rank, ROW_NUMBER() OVER (ORDER BY paid_at DESC, id) AS seq_no, LEAD(amount, 1, 0) OVER (PARTITION BY order_id ORDER BY paid_at, id) AS next_amount_2 FROM payments WINDOW w_part AS (ORDER BY paid_at, id), w_hist AS (PARTITION BY order_id ORDER BY amount)) SELECT seq_no, STDDEV_SAMP(amount) AS amount_stddev, SORT_ARRAY(COLLECT_SET(status)) AS status_list, SIZE(COLLECT_SET(method)) AS num_methods, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN method = 'promptpay' THEN 1 END), 0), 2) AS amount_per_promptpay FROM scored GROUP BY seq_no;
